(()=>{"use strict";const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),en=()=>document.documentElement.lang==="en"||document.documentElement.dir==="ltr",t=(h,e)=>en()?e:h;
async function api(p,o={}){const i={credentials:"same-origin",...o,headers:{...(o.headers||{})}};if(o.body&&!(o.body instanceof FormData)){i.headers["Content-Type"]="application/json";i.body=JSON.stringify(o.body)}let r;try{r=await fetch(p,i)}catch(e){throw new Error(window.GmachDescribeNetworkError?window.GmachDescribeNetworkError(e):t("לא ניתן להתחבר לשרת","Could not connect to the server"))}const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(window.GmachDescribeHttpError?window.GmachDescribeHttpError(r,d):(d.error||t("הפעולה נכשלה","Action failed")));return d}function dlg(id,title){let d=$("#"+id);if(!d){d=document.createElement("dialog");d.id=id;d.className="modal modal-wide";document.body.append(d)}d.innerHTML='<button class="dialog-close">×</button><h2>'+esc(title)+'</h2><div class="privacy-availability-body"></div>';$(".dialog-close",d).onclick=()=>d.close();return d}function toast(s,b=false){let x=$("#pa-toast");if(!x){x=document.createElement("div");x.id="pa-toast";x.style.cssText="position:fixed;z-index:100004;left:50%;bottom:18px;transform:translateX(-50%);padding:12px 16px;border-radius:12px;color:#fff;background:#173a4d";document.body.append(x)}x.style.background=b?"#8f1d27":"#173a4d";x.textContent=s;clearTimeout(x._t);x._t=setTimeout(()=>x.remove(),3000)}
async function openAvailability(){const d=dlg("availability-rules-dialog",t("ניהול זמינות מתקדם","Advanced availability")),b=$(".privacy-availability-body",d);d.showModal();let orgs=[];try{const snap=await api("/api/me/dashboard");orgs=snap.organizations||[]}catch(e){b.textContent=e.message||t("לא ניתן לטעון גמ״חים","Could not load gmachs");return}if(!orgs.length){b.innerHTML="<p>"+t("אין גמ״חים לניהול.","No gmachs to manage.")+"</p>";return}b.innerHTML='<label>'+t("גמ״ח","Gmach")+'<select id="pa-org">'+orgs.map(o=>'<option value="'+esc(o.id)+'">'+esc(o.name)+'</option>').join("")+'</select></label><div id="pa-rules"></div>';const sel=$("#pa-org",d),host=$("#pa-rules",d);async function load(){const x=await api("/api/organizations/"+encodeURIComponent(sel.value)+"/availability-rules");host.innerHTML='<form id="pa-create" class="form-grid"><label>'+t("סוג כלל","Rule type")+'<select name="type"><option value="closure">'+t("סגירה","Closure")+'</option><option value="weekly_window">'+t("חלון שבועי","Weekly window")+'</option><option value="preparation">'+t("זמן הכנה","Preparation")+'</option><option value="advance_limit">'+t("טווח הזמנה מראש","Advance limit")+'</option></select></label><label>'+t("סניף, רשות","Branch, optional")+'<select name="branch"><option value="">'+t("כל הסניפים","All branches")+'</option>'+(x.branches||[]).map(v=>'<option value="'+esc(v.id)+'">'+esc(v.name)+'</option>').join("")+'</select></label><label>'+t("מוצר, רשות","Item, optional")+'<select name="item"><option value="">'+t("כל המוצרים","All items")+'</option>'+(x.items||[]).map(v=>'<option value="'+esc(v.id)+'">'+esc(v.title)+'</option>').join("")+'</select></label><label>'+t("JSON של הכלל","Rule JSON")+'<textarea name="rule" required placeholder=\'{"startsAt":"2026-10-01T08:00","endsAt":"2026-10-01T18:00"}\'></textarea></label><button class="button button-primary">'+t("הוספת כלל","Add rule")+'</button></form><div style="display:grid;gap:8px;margin-top:12px">'+(x.rules||[]).map(r=>'<article class="dashboard-row"><div><strong>'+esc(r.rule_type)+'</strong><p>'+esc(JSON.stringify(r.rule))+'</p><small>'+(r.branch_id?t("סניף","branch")+": "+esc(r.branch_id)+" · ":"")+(r.item_id?t("מוצר","item")+": "+esc(r.item_id)+" · ":"")+(r.active?t("פעיל","active"):t("כבוי","disabled"))+'</small></div><div class="dashboard-row-actions"><button class="button button-secondary button-small" data-rule-toggle="'+esc(r.id)+'" data-active="'+(r.active?"1":"0")+'">'+(r.active?t("השבתה","Disable"):t("הפעלה","Enable"))+'</button><button class="button button-danger button-small" data-rule-delete="'+esc(r.id)+'">'+t("מחיקה","Delete")+'</button></div></article>').join("")+'</div>';$("#pa-create",d).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;let rule;try{rule=JSON.parse(f.rule.value)}catch{return toast(t("JSON לא תקין","Invalid JSON"),true)}try{await api("/api/organizations/"+encodeURIComponent(sel.value)+"/availability-rules",{method:"POST",body:{type:f.type.value,branchId:f.branch.value||null,itemId:f.item.value||null,rule}});toast(t("כלל הזמינות נוסף","Availability rule added"));await load()}catch(err){toast(err.message,true)}};$$("[data-rule-toggle]",d).forEach(x=>x.onclick=async()=>{try{await api("/api/availability-rules/"+encodeURIComponent(x.dataset.ruleToggle),{method:"PATCH",body:{active:x.dataset.active!=="1"}});await load()}catch(e){toast(e.message,true)}});$$("[data-rule-delete]",d).forEach(x=>x.onclick=async()=>{if(!confirm(t("למחוק את כלל הזמינות?","Delete this availability rule?")))return;try{await api("/api/availability-rules/"+encodeURIComponent(x.dataset.ruleDelete),{method:"DELETE",body:{}});await load()}catch(e){toast(e.message,true)}})}sel.onchange=load;await load()}
async function openPrivacyAdmin(){const d=dlg("privacy-requests-admin",t("בקשות פרטיות","Privacy requests")),b=$(".privacy-availability-body",d);d.showModal();async function load(){try{const x=await api("/api/admin/data-requests");b.innerHTML=(x.requests||[]).map(r=>'<article class="dashboard-row"><div><strong>'+esc(r.request_type)+' · '+esc(r.full_name)+'</strong><p>'+esc(r.details||"")+'</p><small>'+esc(r.email)+' · '+esc(r.status)+' · '+esc(r.created_at)+'</small></div><div class="dashboard-row-actions"><select data-privacy-status="'+esc(r.id)+'">'+["open","processing","completed","rejected"].map(s=>'<option '+(s===r.status?"selected":"")+'>'+s+'</option>').join("")+'</select><button class="button button-secondary button-small" data-privacy-save="'+esc(r.id)+'">'+t("עדכון","Update")+'</button></div></article>').join("")||"<p>"+t("אין בקשות פתוחות.","No requests.")+"</p>";$$("[data-privacy-save]",d).forEach(btn=>btn.onclick=async()=>{const status=$('[data-privacy-status="'+CSS.escape(btn.dataset.privacySave)+'"]',d).value,note=prompt(t("הערת מנהל, רשות","Admin note, optional"))||"";try{await api("/api/admin/data-requests/"+encodeURIComponent(btn.dataset.privacySave),{method:"PATCH",body:{status,adminNote:note}});toast(t("הבקשה עודכנה","Request updated"));await load()}catch(e){toast(e.message,true)}})}catch(e){b.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}}await load()}
function install(){const a=$("#dashboard-view .dashboard-actions");if(a&&!a.querySelector("[data-availability-rules]")){const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.availabilityRules="1";b.textContent=t("זמינות מתקדמת","Availability rules");b.onclick=openAvailability;a.prepend(b)}const tab=$("#admin-tab");if(tab&&!tab.hidden&&a&&!a.querySelector("[data-privacy-admin]")){const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.privacyAdmin="1";b.textContent=t("בקשות פרטיות","Privacy requests");b.onclick=openPrivacyAdmin;a.prepend(b)}}function init(){const o=new MutationObserver(install);o.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:["hidden","lang","dir"]});install()}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init()})();